-- Phase 3 Tier 2: Ice Routes Hazard Enrichment
-- Agent 4 - Ice & Mixed Alpine Climbing
-- Generated 2026-07-28

-- Step 1: Verify hazard_tags column exists
ALTER TABLE routes
ADD COLUMN IF NOT EXISTS hazard_tags text[] DEFAULT '{}'::text[];

-- Step 2: Update routes with researched hazards

-- Route 1: Kautz Glacier / Kautz Couloir (Mount Rainier)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['Seracs of the Kautz Ice Cliff present major icefall hazard, especially on descent around Camp Hazard—large ice chunks regularly fall thousands of feet down couloir; position quickly and stay compact with party', 'Multiple significant crevasses with thin snow bridges throughout middle glacier section—bridges collapse with daily warming cycles and climber weight; probe continuously and belay crossings in doubt', 'AI2 ice climbing with rotten, wet suspect ice quality—poor tool and screw placements on thick ice pitches; placement failures have serious consequences; use redundant anchors', 'Descent via Ingraham route passes under seracs during late afternoon—unnerving exposure to falling ice; time descent for cooler morning hours only', 'Penitentes (snow spikes) cover upper Nisqually and upper Kautz sections—exhausting trail breaking through knee-deep snow formations; altitude combined with poor footwork creates summit bid failures', 'Weather exposure with severe wind at Camp Hazard altitude (approximately 10,500 feet)—teams blown off mountain in high wind conditions; retreat decision required before summit push', 'Complex crevasse route-finding on Ingraham Glacier—ladders move and boot pack reroutes overnight; in whiteout visibility becomes critical survival hazard', 'Crumbly rock sections on approach—volcanic debris creates unreliable rock anchors and loose material on rappel routes; verify all anchor placements before committing weight', 'Descent slushy snowfield conditions in afternoon on Muir Snowfield—melting creates collapse risk and difficult descending on weakened snow; start descent before 2 PM']))
WHERE lower(name) ILIKE ANY(ARRAY['%Kautz%', '%Glacier%', '%Kautz%', '%Couloir%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['Seracs of the Kautz Ice Cliff present major icefall hazard, especially on descent around Camp Hazard—large ice chunks regularly fall thousands of feet down couloir; position quickly and stay compact with party', 'Multiple significant crevasses with thin snow bridges throughout middle glacier section—bridges collapse with daily warming cycles and climber weight; probe continuously and belay crossings in doubt', 'AI2 ice climbing with rotten, wet suspect ice quality—poor tool and screw placements on thick ice pitches; placement failures have serious consequences; use redundant anchors', 'Descent via Ingraham route passes under seracs during late afternoon—unnerving exposure to falling ice; time descent for cooler morning hours only', 'Penitentes (snow spikes) cover upper Nisqually and upper Kautz sections—exhausting trail breaking through knee-deep snow formations; altitude combined with poor footwork creates summit bid failures', 'Weather exposure with severe wind at Camp Hazard altitude (approximately 10,500 feet)—teams blown off mountain in high wind conditions; retreat decision required before summit push', 'Complex crevasse route-finding on Ingraham Glacier—ladders move and boot pack reroutes overnight; in whiteout visibility becomes critical survival hazard', 'Crumbly rock sections on approach—volcanic debris creates unreliable rock anchors and loose material on rappel routes; verify all anchor placements before committing weight', 'Descent slushy snowfield conditions in afternoon on Muir Snowfield—melting creates collapse risk and difficult descending on weakened snow; start descent before 2 PM'])
  );

-- Route 2: Tahoma Glacier (Mount Rainier)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['Complex crevasse navigation throughout entire route—most crevasses unconcealed with variable snow bridge conditions; lack of previous tracks requires careful routefinding and continuous probing', 'Serac fall objective danger from ice cliffs above glacier; time climbing to early morning hours to minimize melt-related icefall; position away from direct fall lines from above', 'Highly variable crevasse patterns year-to-year—previous tracks and route assumptions may not apply; route-finding challenges in whiteout conditions where visual landmarks are minimal', 'Terrain trap potential if avalanche occurs on surrounding steep slopes above 9,000-10,000 feet—slopes to sides feed debris into glacier proper; monitor snowpack and avoid climbing after recent heavy precipitation', 'Late season (July+) bare glacier ice becomes extremely hard and slick—crampons essential; blue ice increases fall consequence and decreases screw security; highest rockfall risk from warming mountain', 'Camping requirement at approximately 10,440 feet below Saint Andrews Rock—site exposed to wind and weather; dehydration and altitude sickness compounded by difficult navigation demands', 'Multi-day commitment with limited escape options once on upper glacier—weather deterioration or injury at high altitude creates serious rescue logistics challenges; helicopter rescue difficult due to terrain', 'Traversing high-angle snow (40-60 degrees) with exposed terrain—slip potential on consolidated snow; firm conditions require careful downclimbing if route-finding error occurs']))
WHERE lower(name) ILIKE ANY(ARRAY['%Tahoma%', '%Glacier%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['Complex crevasse navigation throughout entire route—most crevasses unconcealed with variable snow bridge conditions; lack of previous tracks requires careful routefinding and continuous probing', 'Serac fall objective danger from ice cliffs above glacier; time climbing to early morning hours to minimize melt-related icefall; position away from direct fall lines from above', 'Highly variable crevasse patterns year-to-year—previous tracks and route assumptions may not apply; route-finding challenges in whiteout conditions where visual landmarks are minimal', 'Terrain trap potential if avalanche occurs on surrounding steep slopes above 9,000-10,000 feet—slopes to sides feed debris into glacier proper; monitor snowpack and avoid climbing after recent heavy precipitation', 'Late season (July+) bare glacier ice becomes extremely hard and slick—crampons essential; blue ice increases fall consequence and decreases screw security; highest rockfall risk from warming mountain', 'Camping requirement at approximately 10,440 feet below Saint Andrews Rock—site exposed to wind and weather; dehydration and altitude sickness compounded by difficult navigation demands', 'Multi-day commitment with limited escape options once on upper glacier—weather deterioration or injury at high altitude creates serious rescue logistics challenges; helicopter rescue difficult due to terrain', 'Traversing high-angle snow (40-60 degrees) with exposed terrain—slip potential on consolidated snow; firm conditions require careful downclimbing if route-finding error occurs'])
  );

-- Route 3: Nisqually Glacier Route (Mount Rainier)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['Penitentes (radiation-formed snow spikes) cover upper Nisqually sections at 12,000+ feet—40-60 degree slope with dense spikes creating exhausting trail-breaking; altitude combined with snow depth leads to summit bid failure', 'Large bergschrund near summit requires careful crossing—may be significant obstacle mid-season with fall hazard potential; probe and belay crossing if uncertain of snow bridge stability', 'Rockfall from surrounding terrain on exposure zones—afternoon warming increases activity; start before dawn and move efficiently through exposure areas', 'Crevasses throughout glacier with variable snow bridge reliability—particularly complex on Wilson Glacier approach where multiple crack systems require careful rope team movement', 'Descent encounters slushy Muir Snowfield (afternoon conditions)—collapse risk on weakened snow and slip hazard even on steep slopes; time descent to complete before afternoon melt accelerates', 'Long exposure during approach traverse across Nisqually—repeated snow bridge crossings with climbing fatigue accumulated; careful protection placement essential as day wears on', 'Weather exposure at altitude with rapid deterioration common—whiteout conditions erase visual landmarks making route-finding hazardous on descent; GPS/compass essential', 'Mandatory helmet use throughout—rockfall and icefall objective hazards present from first pitch to summit; head impacts have serious consequences at altitude']))
WHERE lower(name) ILIKE ANY(ARRAY['%Nisqually%', '%Glacier%', '%Route%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['Penitentes (radiation-formed snow spikes) cover upper Nisqually sections at 12,000+ feet—40-60 degree slope with dense spikes creating exhausting trail-breaking; altitude combined with snow depth leads to summit bid failure', 'Large bergschrund near summit requires careful crossing—may be significant obstacle mid-season with fall hazard potential; probe and belay crossing if uncertain of snow bridge stability', 'Rockfall from surrounding terrain on exposure zones—afternoon warming increases activity; start before dawn and move efficiently through exposure areas', 'Crevasses throughout glacier with variable snow bridge reliability—particularly complex on Wilson Glacier approach where multiple crack systems require careful rope team movement', 'Descent encounters slushy Muir Snowfield (afternoon conditions)—collapse risk on weakened snow and slip hazard even on steep slopes; time descent to complete before afternoon melt accelerates', 'Long exposure during approach traverse across Nisqually—repeated snow bridge crossings with climbing fatigue accumulated; careful protection placement essential as day wears on', 'Weather exposure at altitude with rapid deterioration common—whiteout conditions erase visual landmarks making route-finding hazardous on descent; GPS/compass essential', 'Mandatory helmet use throughout—rockfall and icefall objective hazards present from first pitch to summit; head impacts have serious consequences at altitude'])
  );

-- Route 4: Fryingpan Glacier / Whitman Crest Route (Mount Rainier)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['Uneven glacier topography with extensive crevasse field—surface crevasses and hidden features create route-finding hazard; particularly dangerous when covered by thin snow bridges that collapse under team weight', 'Whitman Notch crossing between Fryingpan and Whitman Glaciers presents navigation challenge—correct pass location essential to avoid wandering into steeper glacier sections; visual landmarks minimal in poor visibility', 'Multiple crevasse rescue scenarios likely on this less-traveled route—fewer established camps mean minimal aid from subsequent parties; self-rescue capability essential', 'Little Tahoma Peak summit block rock climbing (Class 3-4)—loose volcanic rock prevalent; rockfall hazard from weather action and climber-induced fall lines; secure all protection placements', 'Descent route complexity—multiple variations available (East Ridge, Fryingpan descent) creating potential for navigation error and unplanned altitude loss; verify descent plan with party before ascending', 'Exposure on Fryingpan Glacier eastern edge where terrain drops to Cowlitz region—concentration required to maintain safe line away from break-over points', 'Long day requirements (8-10 hours) from trailhead to summit combined with elevation (11,138 ft on Little Tahoma)—altitude sickness compounded by navigation demands increases error risk late in day', 'Remote location with minimal rescue access—emergency situation resolution depends entirely on team self-rescue capability; communication challenges due to Mt. Rainier''s prominence blocking signals']))
WHERE lower(name) ILIKE ANY(ARRAY['%Fryingpan%', '%Glacier%', '%Whitman%', '%Crest%', '%Route%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['Uneven glacier topography with extensive crevasse field—surface crevasses and hidden features create route-finding hazard; particularly dangerous when covered by thin snow bridges that collapse under team weight', 'Whitman Notch crossing between Fryingpan and Whitman Glaciers presents navigation challenge—correct pass location essential to avoid wandering into steeper glacier sections; visual landmarks minimal in poor visibility', 'Multiple crevasse rescue scenarios likely on this less-traveled route—fewer established camps mean minimal aid from subsequent parties; self-rescue capability essential', 'Little Tahoma Peak summit block rock climbing (Class 3-4)—loose volcanic rock prevalent; rockfall hazard from weather action and climber-induced fall lines; secure all protection placements', 'Descent route complexity—multiple variations available (East Ridge, Fryingpan descent) creating potential for navigation error and unplanned altitude loss; verify descent plan with party before ascending', 'Exposure on Fryingpan Glacier eastern edge where terrain drops to Cowlitz region—concentration required to maintain safe line away from break-over points', 'Long day requirements (8-10 hours) from trailhead to summit combined with elevation (11,138 ft on Little Tahoma)—altitude sickness compounded by navigation demands increases error risk late in day', 'Remote location with minimal rescue access—emergency situation resolution depends entirely on team self-rescue capability; communication challenges due to Mt. Rainier''s prominence blocking signals'])
  );

