  );

-- Route 11: Mount Olympus Blue Glacier (Mount Olympus, Olympic Mountains)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['Many crevasses throughout upper glacier halves with extensive crevasse field—dense crack systems with thin snow bridges; continuous probing required; bridges collapse with daily warming cycles and climber weight', 'Icefalls and bergschrunds on upper glacier—10-foot-wide crevasses to negotiate; serac hazard from ice cliffs above glacier; position parties quickly and move through exposure zones efficiently', 'Blue Glacier hardening (late season)—bare ice sections become extremely hard mid-summer (July+); crampons essential; blue ice reduces screw placement security and fall consequence becomes major', 'Fourth of July route (direct from lower glacier) avalanche hazard—steep accumulation zone; soft slab formation possible following storms; Crystal Pass route generally safer but longer', 'Summit block Class 4 loose rock scramble—final pitch climbs on unstable granite with loose rock prevalent; significant exposure; careful handhold testing essential; helmet mandatory', 'Crystal Pass approach alternative presents route-finding complexity—longer route alternative; navigation hazard in whiteout conditions; multiple descent options create potential confusion', 'Remote location with 17+ mile approach via Hoh River—long approach creates time pressure at altitude; rescue logistics extremely complex; self-rescue essential', 'Rapid weather deterioration common in Olympics—maritime air masses produce sudden storms; whiteout conditions on descent create serious navigation hazard; compass and GPS essential', '3-4 day commitment at altitude (10,000+ feet on Blue Glacier)—altitude sickness risk compounded by navigation demands and weather exposure; dehydration significant on long glacier traverses']))
WHERE lower(name) ILIKE ANY(ARRAY['%Mount%', '%Olympus%', '%Blue%', '%Glacier%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['Many crevasses throughout upper glacier halves with extensive crevasse field—dense crack systems with thin snow bridges; continuous probing required; bridges collapse with daily warming cycles and climber weight', 'Icefalls and bergschrunds on upper glacier—10-foot-wide crevasses to negotiate; serac hazard from ice cliffs above glacier; position parties quickly and move through exposure zones efficiently', 'Blue Glacier hardening (late season)—bare ice sections become extremely hard mid-summer (July+); crampons essential; blue ice reduces screw placement security and fall consequence becomes major', 'Fourth of July route (direct from lower glacier) avalanche hazard—steep accumulation zone; soft slab formation possible following storms; Crystal Pass route generally safer but longer', 'Summit block Class 4 loose rock scramble—final pitch climbs on unstable granite with loose rock prevalent; significant exposure; careful handhold testing essential; helmet mandatory', 'Crystal Pass approach alternative presents route-finding complexity—longer route alternative; navigation hazard in whiteout conditions; multiple descent options create potential confusion', 'Remote location with 17+ mile approach via Hoh River—long approach creates time pressure at altitude; rescue logistics extremely complex; self-rescue essential', 'Rapid weather deterioration common in Olympics—maritime air masses produce sudden storms; whiteout conditions on descent create serious navigation hazard; compass and GPS essential', '3-4 day commitment at altitude (10,000+ feet on Blue Glacier)—altitude sickness risk compounded by navigation demands and weather exposure; dehydration significant on long glacier traverses'])
  );

-- Route 12: Forbidden Peak West Ridge (Forbidden Peak, North Cascades)
UPDATE routes SET hazard_tags = array_distinct(array_cat(COALESCE(hazard_tags, '{}'::text[]), ARRAY['40-50 degree snow and ice in West Ridge Couloir—sustained steep terrain with variable conditions; spring ice consolidation vs winter powder affects difficulty and hazard profile; slip consequence major', 'Upper rock band (mid-5th class exposed crest to summit)—significant exposure on broken sedimentary rock; loose rock prevalent; handholds and footholds require careful testing; fall hazard with serious consequence', 'Small glacier below South Face requires crevasse travel—relatively straightforward but requires rope team proficiency; snow bridge stability variable; continuous monitoring essential', 'Colorado-to-Constance traverse descent complexity—alternate descent via Bailey Range creates potential for navigation error and route-finding hazard in whiteout conditions', 'Northwest Face approach avalanche exposure—soft slab formation potential on background slopes (30-45 degrees); avoid climbing within 24-48 hours of heavy snow; route passes through accumulation zone', 'Wind-loading on north-facing couloir—exposed ridge orientation accumulates wind-loaded snow; slab formation possible; traverse terrain exposed to wind-scoured ice and rime', 'Weather exposure at altitude—rapid deterioration common in North Cascades; whiteout visibility eliminates landmarks; descent route-finding becomes critical hazard in low visibility', 'Long day commitment with light snow and ice climbing (4-6+ hours typical)—winter daylight constraint forces tactical decisions; partial daylight descent hazard increases error risk']))
WHERE lower(name) ILIKE ANY(ARRAY['%Forbidden%', '%Peak%', '%West%', '%Ridge%'])
  AND state = 'WA'
  AND NOT EXISTS (
    SELECT 1 FROM (SELECT unnest(hazard_tags) as tag) t
    WHERE t.tag = ANY(ARRAY['40-50 degree snow and ice in West Ridge Couloir—sustained steep terrain with variable conditions; spring ice consolidation vs winter powder affects difficulty and hazard profile; slip consequence major', 'Upper rock band (mid-5th class exposed crest to summit)—significant exposure on broken sedimentary rock; loose rock prevalent; handholds and footholds require careful testing; fall hazard with serious consequence', 'Small glacier below South Face requires crevasse travel—relatively straightforward but requires rope team proficiency; snow bridge stability variable; continuous monitoring essential', 'Colorado-to-Constance traverse descent complexity—alternate descent via Bailey Range creates potential for navigation error and route-finding hazard in whiteout conditions', 'Northwest Face approach avalanche exposure—soft slab formation potential on background slopes (30-45 degrees); avoid climbing within 24-48 hours of heavy snow; route passes through accumulation zone', 'Wind-loading on north-facing couloir—exposed ridge orientation accumulates wind-loaded snow; slab formation possible; traverse terrain exposed to wind-scoured ice and rime', 'Weather exposure at altitude—rapid deterioration common in North Cascades; whiteout visibility eliminates landmarks; descent route-finding becomes critical hazard in low visibility', 'Long day commitment with light snow and ice climbing (4-6+ hours typical)—winter daylight constraint forces tactical decisions; partial daylight descent hazard increases error risk'])
  );


-- Step 3: Verification query
SELECT
  COUNT(*) as total_routes,
  COUNT(CASE WHEN hazard_tags IS NOT NULL AND array_length(hazard_tags, 1) > 0 THEN 1 END) as routes_with_hazards,
  ROUND(100.0 * COUNT(CASE WHEN hazard_tags IS NOT NULL AND array_length(hazard_tags, 1) > 0 THEN 1 END) / COUNT(*), 2) as coverage_pct
FROM routes
WHERE state = 'WA';

